#!/bin/bash
# Downloads the data of the third batch of confirmatory relations (downloaded on 2026-11-03 and 2026-11-04) into
# $RAW/<source>/.  Nothing is unpacked or read here: every relation was fixed from its documentation before its data
# were opened.  Each file's HTTP status, size and sha256 go to $RAW/MANIFEST.tsv; a file recorded with 200 is kept on a rerun.
# The three BenchBase benchmarks and Synthea are generated by gen_fresh3.sh.  Subsets: whole files of the download day;
# Companies House part1_7; Stack Exchange site 3dprinting; FEC cycle 2023-2024; NPPES the monthly full-replacement file;
# GLEIF the golden copy of the day; ONSPD August 2026 (the latest edition).
# Usage:  RAW=<dir> bash download_fresh3.sh small|big|op   (op: CMS Open Payments, program year 2024)
set -u
RAW=${RAW:-$PWD/fresh_raw3}
mkdir -p "$RAW" && cd "$RAW" || exit 1
UA="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/130.0 Safari/537.36"
[ -s MANIFEST.tsv ] || printf 'date\tsource\tfile\thttp\tbytes\tsha256\turl\n' > MANIFEST.tsv
get() {   # source, file, url
  mkdir -p "$1"
  if [ -s "$1/$2" ] && awk -F'\t' -v s="$1" -v f="$2" '$2==s && $3==f && $4==200 {ok=1} END {exit !ok}' MANIFEST.tsv; then echo "$1/$2 kept"; return; fi
  code=$(curl -sSL -A "$UA" --retry 3 --max-time 14400 -o "$1/$2" -w "%{http_code}" "$3")
  printf '%s\t%s\t%s\t%s\t%s\t%s\t%s\n' "$(date -u +%FT%TZ)" "$1" "$2" "$code" "$(stat -c %s "$1/$2" 2>/dev/null)" \
    "$(sha256sum "$1/$2" | cut -c1-64)" "$3" >> MANIFEST.tsv
  echo "$1/$2 $code $(stat -c %s "$1/$2" 2>/dev/null) $(date -u +%T)"
}
case "${1:-small}" in
small)
  # 1 HGNC complete set (the current file of the HGNC download archive)
  get hgnc hgnc_complete_set.txt https://storage.googleapis.com/public-download-files/hgnc/tsv/tsv/hgnc_complete_set.txt
  # 2 GLEIF code lists (the golden copy itself is in group big)
  get gleif 2026-09-30_ra-list-v1.9.csv https://www.gleif.org/lei-data/code-lists/gleif-registration-authorities-list/2026-09-30_ra-list-v1.9.csv
  get gleif 2026-02-19-elf-code-list-v1.6.csv https://www.gleif.org/lei-data/code-lists/iso-20275-entity-legal-forms-code-list/2026-02-19-elf-code-list-v1.6.csv
  # 3 ONSPD August 2026 (Open Geography Portal item 9e5a92a3cfb14dc7ad43d6ea7a7b8c7f, ONSPD_AUG_2026.zip)
  get onspd ONSPD_AUG_2026.zip https://www.arcgis.com/sharing/rest/content/items/9e5a92a3cfb14dc7ad43d6ea7a7b8c7f/data
  # 4 FEC 2023-2024: candidate master, committee master, candidate-committee linkage
  get fec cn24.zip https://www.fec.gov/files/bulk-downloads/2024/cn24.zip
  get fec cm24.zip https://www.fec.gov/files/bulk-downloads/2024/cm24.zip
  get fec ccl24.zip https://www.fec.gov/files/bulk-downloads/2024/ccl24.zip
  # 5 OpenFlights (downloaded for the record; excluded by the selection rules)
  get openflights airports.dat https://raw.githubusercontent.com/jpatokal/openflights/master/data/airports.dat
  get openflights countries.dat https://raw.githubusercontent.com/jpatokal/openflights/master/data/countries.dat
  # 6 OurAirports
  for f in airports.csv countries.csv regions.csv; do get ourairports "$f" "https://davidmegginson.github.io/ourairports-data/$f"; done
  # 8 Companies House: the first part file of the 2026-11-01 snapshot
  get companieshouse BasicCompanyData-2026-11-01-part1_7.zip http://download.companieshouse.gov.uk/BasicCompanyData-2026-11-01-part1_7.zip
  # 10 Stack Exchange data dump, site 3dprinting.stackexchange.com
  get stackexchange 3dprinting.stackexchange.com.7z https://archive.org/download/stackexchange/3dprinting.stackexchange.com.7z
  echo "== small done $(date)";;
big)
  # 2 GLEIF Level 1 golden copy, 2026-11-03 16:00 (the latest at download time; the api answer is in docs/fresh3)
  get gleif 20261103-1600-gleif-goldencopy-lei2-golden-copy.csv.zip https://goldencopy.gleif.org/storage/golden-copy-files/2026/11/03/1296605/20261103-1600-gleif-goldencopy-lei2-golden-copy.csv.zip
  # 7 NPPES monthly full replacement file, November 2026
  get nppes NPPES_Data_Dissemination_November_2026_V2.zip https://download.cms.gov/nppes/NPPES_Data_Dissemination_November_2026_V2.zip
  echo "== big done $(date)";;
op)
  # 9 CMS Open Payments, program year 2024 general payments and recipient profiles (URLs resolved from openpaymentsdata.cms.gov)
  get openpayments OP_DTL_GNRL_PGYR2024_P06302026_06032026.csv https://download.cms.gov/openpayments/PGYR2024_P06302026_06032026/OP_DTL_GNRL_PGYR2024_P06302026_06032026.csv
  get openpayments OP_CVRD_RCPNT_PRFL_SPLMTL_P06302026_06032026.csv https://download.cms.gov/openpayments/PHPRFL_P06302026_06032026/OP_CVRD_RCPNT_PRFL_SPLMTL_P06302026_06032026.csv
  get openpayments OP_PGYR2024_README_P06302026.txt https://download.cms.gov/openpayments/PGYR2024_P06302026_06032026/OP_PGYR2024_README_P06302026.txt
  echo "== op done $(date)";;
esac
